import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.eFe5Lsvn.js";const b=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"lib/installation.md","filePath":"lib/installation.md"}'),n={name:"lib/installation.md"};function s(r,e,d,l,h,p){return a(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>MayhemLib is the robot-side library for Mayhem trajectories on WPILib 2026 (FRC REBUILT). It is Java 17, package <code>mayhemlib</code>, published as <code>mayhemlib:MayhemLib-java</code>.</p><p>It is built against WPILib 2026.2.x, Phoenix 6 26.x (optional, used for <code>CtreSwerve</code>), and SleipnirJava 2026 (optional, used for <code>SleipnirBridgeRefiner</code>). All three are <code>compileOnly</code> dependencies: your robot project supplies them, and MayhemLib bundles none of them.</p><h2 id="option-a-online-install-recommended" tabindex="-1">Option A: online install (recommended) <a class="header-anchor" href="#option-a-online-install-recommended" aria-label="Permalink to &quot;Option A: online install (recommended)&quot;">​</a></h2><p>In VS Code with the WPILib extension, open the command palette (<kbd>Ctrl</kbd>/<kbd>Cmd</kbd>+<kbd>Shift</kbd>+<kbd>P</kbd>), run <strong>WPILib: Manage Vendor Libraries</strong>, choose <strong>Install new libraries (online)</strong>, and paste:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://ryanabraham1.github.io/Mayhem/MayhemLib.json</span></span></code></pre></div><p>That writes <code>vendordeps/MayhemLib.json</code> into your project. The first Gradle build then downloads the library from the hosted maven repository, so it works on every machine with no extra setup. Commit the JSON, and teammates and CI get it with the repo.</p><p>Without VS Code, download the same file into your project instead:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vendordeps/MayhemLib.json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://ryanabraham1.github.io/Mayhem/MayhemLib.json</span></span></code></pre></div><p>To update, run <strong>Manage Vendor Libraries</strong>, then <strong>Check for updates (online)</strong>. WPILib compares the version in your <code>vendordeps/MayhemLib.json</code> with the one hosted at that URL and offers the new one.</p><h2 id="option-b-offline-from-a-release" tabindex="-1">Option B: offline (from a release) <a class="header-anchor" href="#option-b-offline-from-a-release" aria-label="Permalink to &quot;Option B: offline (from a release)&quot;">​</a></h2><p>Download <code>MayhemLib-maven.zip</code> and <code>MayhemLib.json</code> from the <a href="https://github.com/ryanabraham1/Mayhem/releases/latest" target="_blank" rel="noreferrer">latest release</a>. Unzip the zip into <code>~/wpilib/2026/maven</code> (Windows: <code>C:\\Users\\Public\\wpilib\\2026\\maven</code>), which GradleRIO always searches, and copy <code>MayhemLib.json</code> into your project&#39;s <code>vendordeps/</code>. Every machine that builds the robot code needs the unzipped artifact.</p><h2 id="option-c-from-a-checkout-library-development" tabindex="-1">Option C: from a checkout (library development) <a class="header-anchor" href="#option-c-from-a-checkout-library-development" aria-label="Permalink to &quot;Option C: from a checkout (library development)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lib</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> installVendordep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ProbotProject=/path/to/your/robot/project</span></span></code></pre></div><p>This publishes the jar to <code>~/wpilib/2026/maven</code> and writes <code>vendordeps/MayhemLib.json</code> into your robot project. Leave off <code>-ProbotProject</code> to only publish. To try a different version, add <code>-PmayhemVersion=2026.3.1</code>. Run it again after each change to the library.</p><h2 id="robot-project-requirements" tabindex="-1">Robot project requirements <a class="header-anchor" href="#robot-project-requirements" aria-label="Permalink to &quot;Robot project requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dependency</th><th>Needed for</th><th>How to get it</th></tr></thead><tbody><tr><td>WPILib 2026 GradleRIO (<code>2026.2.1</code> or newer)</td><td>everything</td><td>WPILib installer</td></tr><tr><td>Phoenix 6 vendordep</td><td><code>mayhemlib.ctre.CtreSwerve</code></td><td><code>https://maven.ctr-electronics.com/release/com/ctre/phoenix6/latest/Phoenix6-frc2026-latest.json</code></td></tr><tr><td>SleipnirJava vendordep</td><td><code>SleipnirBridgeRefiner</code> only</td><td><code>https://file.tavsys.net/sleipnir/SleipnirJava.json</code></td></tr></tbody></table><p>Building MayhemLib itself needs JDK 17 or newer. The bytecode always targets Java 17 (<code>--release 17</code>).</p>`,18)])])}const m=t(n,[["render",s]]);export{b as __pageData,m as default};
